import 'package:flutter/material.dart';

class MyAppData extends InheritedWidget {
  final String userName;
  final Color themeColor;

  const MyAppData({
    Key? key,
    required this.userName,
    required this.themeColor,
    required Widget child,
  }) : super(key: key, child: child);

  @override
  bool updateShouldNotify(covariant MyAppData oldWidget) {
    return oldWidget.userName != userName || oldWidget.themeColor != themeColor;
  }

  static MyAppData? of(BuildContext context) {
    return context.dependOnInheritedWidgetOfExactType<MyAppData>();
  }
}

class MyAppRoot extends StatefulWidget {
  const MyAppRoot({Key? key}) : super(key: key);

  @override
  _MyAppRootState createState() => _MyAppRootState();
}

class _MyAppRootState extends State<MyAppRoot> {
  String _currentUser = "Alice";
  Color _currentColor = Colors.blue;

  void _changeUser() {
    setState(() {
      _currentUser = _currentUser == "Alice" ? "Bob" : "Alice";
      _currentColor = _currentColor == Colors.blue ? Colors.green : Colors.blue;
    });
  }

  @override
  Widget build(BuildContext context) {
    return MyAppData(
      userName: _currentUser,
      themeColor: _currentColor,
      child: MaterialApp(
        home: Scaffold(
          appBar: AppBar(title: Text('InheritedWidget Demo')),
          body: Column(
            children: [
              UserProfile(),
              SizedBox(height: 20),
              ElevatedButton(
                onPressed: _changeUser,
                child: Text('Change User & Color'),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class UserProfile extends StatelessWidget {
  const UserProfile({Key? key}) : super(key: key);

  @override
  Widget build(BuildContext context) {
    final appData = MyAppData.of(context);

    if (appData == null) {
      return Center(child: Text("MyAppData not found!"));
    }

    return Container(
      padding: EdgeInsets.all(16.0),
      color: appData.themeColor.withOpacity(0.2),
      child: Center(
        child: Text(
          'Hello, ${appData.userName}!',
          style: TextStyle(fontSize: 24, color: appData.themeColor),
        ),
      ),
    );
  }
}
